    content: `## 매년 12월이 되면 직장인들이 하는 고민

"과장님, 연말정산 세액공제 최대로 받으려면 900만 원 채워야 한다는데 연금저축펀드랑 IRP 중에 뭐를 만들어야 하나요?"

은행 창구에 가면 수수료와 예치금 유치를 위해 IRP를 적극 권유하는 경우가 많습니다. 하지만 10년 넘게 연금 계좌를 운용해 본 제 결론은 확고합니다.

**"무조건 연금저축펀드 600만 원을 먼저 채우고, 여유 자금이 있을 때 IRP에 300만 원을 넣으세요."**

그 이유를 3가지 핵심 차이점으로 설명해 드립니다.

---

## 1. 차이점 1: 위험자산(주식형 ETF) 투자 한도

- **연금저축펀드:** 위험자산 한도 규제가 없습니다. S&P500이나 미국 나스닥100, 배당 다우존스 등 주식형 ETF를 **내 돈의 100% 전액** 투자할 수 있습니다.
- **IRP (개인형 퇴직연금):** 법적으로 **위험자산 투자 한도가 70%**로 묶여 있습니다. 나머지 30%는 원리금보장 상품(예금)이나 채권형 펀드 등 안전자산에 강제로 묶어두어야 합니다.

젊은 직장인일수록 20~30년간 장기 복리 효과를 누려야 하므로 주식 비중을 100% 가져갈 수 있는 연금저축펀드가 장기 수익률에서 압도적으로 유리합니다.

---

## 2. 차이점 2: 중도 인출의 유연성 (인생의 비상사태)

살다 보면 집을 사거나 가족이 아파서 목돈이 급하게 필요할 때가 있습니다.

- **연금저축펀드:** 계좌를 해지하지 않고 **내가 원하는 금액만 '일부 인출'**할 수 있습니다. (세액공제 안 받은 원금은 비과세 인출 가능, 공제받은 금액은 16.5% 기타소득세 내고 인출 가능)
- **IRP:** **일부 인출이 원칙적으로 전면 금지**되어 있습니다. 무주택자의 내 집 마련이나 6개월 이상 요양 등 법정 사유가 아니면 100만 원이 필요해도 계좌 전체를 해지해 그동안 받은 세제 혜택을 전부 토해내야 합니다.

---

## 3. 차이점 3: 수수료와 세액공제 우선순위

| 구분 | 연금저축펀드 | 개인형 IRP |
| :--- | :--- | :--- |
| **세액공제 납입 한도** | 최대 600만 원 | 연금저축 합산 900만 원 (단독 가능) |
| **주식 ETF 투자 비중** | **100% 가능** | **최대 70% 제한** (30% 채권/예금) |
| **계좌 운용관리 수수료** | 대부분 증권사 무료 (0원) | 증권사 비대면 개설 시 무료 |
| **중도 인출** | **일부 인출 자유로움** | **법정 사유 외 전면 불가** |

제가 지난 10년간 두 계좌를 직접 굴려보며 정착한 가장 속 편한 루틴은 이렇습니다: **연금저축펀드에 매월 50만 원씩 연 600만 원을 자동이체**해 두고, 연말 11~12월 보너스나 여유 자금이 생길 때 IRP에 300만 원을 추가 납입하여 총 900만 원(148.5만 원 환급) 한도를 완성하는 것입니다.`
