"과장님, 제가 작년에 부산이랑 광주 출장을 스무 번 넘게 다녔거든요. KTX비랑 숙박비로 쓴 300만 원이 제 연간 총급여에 합산되어 있어서 세금이 더 나왔어요. 내 돈 쓰고 돌려받은 건데 이게 왜 월급인가요?"

