    content: `## 초등학교 입학하는 아이, 퇴사 말고 '단축근무'를 선택한 이유

저희 팀 후배가 올해 초등학생이 된 첫째 아이 하교 문제로 깊은 고민에 빠졌습니다.

"과장님, 학원 뺑뺑이를 돌리자니 아이가 너무 안쓰럽고, 퇴사하자니 생활비와 대출 이자가 무섭습니다. 방법이 없을까요?"

제가 후배에게 즉시 사내 인사규정을 보여주며 권한 것이 바로 **'육아기 근로시간 단축 제도'**였습니다. 지금 후배는 매일 오후 4시에 퇴근하며 아이를 직접 맞이하고 있습니다.

---

## 1. 육아기 근로시간 단축이란?

남녀고용평등법에 따라 근로자가 만 12세 이하(초등 6학년 이하) 자녀 양육을 위해 주당 15시간 이상 35시간 이하로 근로시간을 줄여 일할 수 있는 법적 권리입니다.

- **사용 기간:** 기본 1년 (육아휴직 미사용 기간이 있다면 합산하여 **최대 3년까지** 연장 가능)
- **근무 형태:** 통상 주 40시간 근무자라면 하루 1~2시간씩 단축하여 주 30~35시간 근무

---

## 2. 줄어든 월급은 고용보험에서 어떻게 메꿔줄까?

회사에서는 일하지 않은 시간만큼 급여를 깎지만, **그 부족분을 고용보험 국고 지원금으로 채워줍니다.**

### [정부 급여 지원 산식]
1. **최초 단축 주 5시간분:**  
   (통상임금 100% 기준 × 5시간 / 40시간) → **통상임금 상한 월 200만 원 기준 전액 지급**
2. **나머지 단축분 (예: 추가 5시간):**  
   (통상임금 80% 기준 × 5시간 / 40시간) → **통상임금 상한 월 150만 원 기준 지급**

예를 들어 통상임금 300만 원인 직장인이 하루 1시간(주 5시간)을 줄이면:
- 회사 지급 급여: 300만 원 × (35/40) = **262.5만 원**
- 고용보험 지원금: 200만 원 × (5/40) = **25만 원**
- **실제 합산 실수령액:** 약 **287.5만 원 (기존 월급의 96% 유지!)**

매일 1시간 일찍 퇴근하면서 잃게 되는 소득은 고작 12만 원에 불과합니다.

---

## 3. 회사 눈치 안 보고 신청하는 3단계 절차

1. **회사 신청:** 단축 개시 예정일 30일 전까지 회사 인사팀에 [육아기 근로시간 단축 신청서] 제출 (사유, 단축 시간, 자녀 정보 기재)
2. **사업주 의무:** 법적으로 사업주는 정당한 사유(대체인력 채용 불가 등)가 없는 한 거부할 수 없습니다.
3. **고용24 급여 청구:** 단축 근무 시작 후 1개월이 지난 시점부터 매달 '고용24(work24.go.kr)' 웹사이트나 모바일 앱에서 지원금을 신청하면 지정 계좌로 입금됩니다.`
