    content: `## 달러로 직접 사는 미국 주식, 세금 떼고 나면 남는 게 없다?

월급날마다 미국 배당 성장주 ETF인 SCHD나 S&P500 지수 ETF를 50만 원, 100만 원씩 꾸준히 매수하는 분들이 정말 많습니다.

그런데 계좌를 확인해 보면 매 분기 입금되는 달러 배당금에서 **미국 세금 15%가 꼬박꼬박 빠져나간 채 85%만 입금**되는 것을 보셨을 것입니다. 

만약 이 투자를 해외 직투가 아닌 **'국내 상장 해외 ETF + 중개형 ISA'** 조합으로 바꾼다면 세금을 얼마나 아낄 수 있을까요?

---

## 1. 해외 직투 vs 중개형 ISA 세금 구조 비교

| 항목 | 미국 직투 (달러 직접 매수) | 국내 상장 해외 ETF (중개형 ISA) |
| :--- | :--- | :--- |
| **매매차익 세금** | 연 250만 원 공제 후 **양도세 22%** | **비과세 200~400만 원 + 초과분 9.9%** |
| **배당금 세금** | 배당 시마다 **15% 원천징수** | **계좌 내 세금 0원 (인출 시 9.9% 정산)** |
| **손익 통산** | 주식 간 매매차익만 통산 | **계좌 내 모든 손익(이자·배당·매매차익) 통산** |
| **종합소득 합산** | 배당금은 2천만 원 초과 시 합산 | **전액 분리과세 (종합과세 합산 배제)** |

---

## 2. ISA 계좌의 결정적 강점: '배당금 100% 재투자'

해외 직투 계좌에서 배당금 100만 원이 나오면 15만 원이 세금으로 뜯기고 85만 원어치 주식만 더 살 수 있습니다.

하지만 중개형 ISA 계좌에서 국내 상장 ETF(예: TIGER 미국배당다우존스, ACE 미국S&P500)를 보유하면:
- 분배금(배당금)이 들어올 때 **세금을 1원도 떼지 않고 100만 원 전액이 계좌 예수금으로 꽂힙니다.**
- 세전 100만 원 그대로 주식을 재매수할 수 있어, 15%의 세금마저도 복리로 굴러가는 마법이 발생합니다.
- 세금은 오직 3년 뒤 계좌를 해지하고 돈을 인출할 때, 비과세 한도(200~400만 원)를 뺀 나머지 차액에 대해서만 9.9%로 딱 한 번 정산합니다.

---

## 3. 박과장의 실전 투자 팁: 3년 주기 연금 전환 테크트리

중개형 ISA의 의무 가입 기간은 3년입니다. 3년이 지난 후 계좌를 해약하면서 자금을 '연금저축계좌'나 'IRP'로 이전하면:
- 이전 금액의 **10%(최대 300만 원)를 추가로 세액공제**받을 수 있습니다.
- 3년마다 ISA 계좌를 리셋하면서 비과세 혜택을 챙기고, 연금 계좌 세액공제까지 더블로 챙기는 것이 대한민국 직장인의 가장 완벽한 절세 공식입니다.`
