    content: `## 첫 출근날 내민 근로계약서, "수습이라 90%만 줍니다"?

이직이나 첫 취업에 성공해 설레는 마음으로 첫 출근을 한 날, 인사팀에서 근로계약서를 내밀며 말합니다.

"저희 회사는 사규상 입사 후 3개월간 수습 평가 기간을 두며, 이 기간에는 월 급여의 90%를 지급합니다."

많은 청년 구직자들이 "법적으로 수습 3개월 90%는 원래 다 그런 거 아닌가?" 하고 무심코 서명하지만, **경우에 따라 이는 명백한 최저임금법 위반이자 임금체불에 해당합니다.**

---

## 1. 수습 90% 감액 지급이 합법인 엄격한 3대 조건

최저임금법 제5조 제2항에 따라 최저임금의 90%만 지급할 수 있으려면 **다음 3가지 조건을 모두 충족**해야 합니다.

1. **근로계약 기간이 1년 이상일 것:** 정규직이거나 최소 1년 이상의 계약직이어야 합니다. 3개월, 6개월짜리 단기 계약직에게 수습 90%를 적용하면 즉시 법 위반입니다.
2. **수습 시작일로부터 3개월 이내일 것:** 수습기간을 6개월로 정했더라도 최저임금의 90% 감액은 **오직 최초 3개월까지만 허용**됩니다. 4개월 차부터는 무조건 100%를 지급해야 합니다.
3. **단순노무직 종사자가 아닐 것:** 편의점 알바, 패스트푸드 주방보조, 주유원 등 한국표준직업분류상 '단순노무직'은 1년 계약이라도 수습 감액이 전면 금지되어 있으며 첫날부터 100%를 주어야 합니다.

---

## 2. 수습기간이라고 주휴수당이나 4대보험을 안 준다?

- **주휴수당:** 수습기간이라고 해서 주휴수당이 빠지지 않습니다. 주 15시간 이상 일하고 개근했다면 주휴수당은 100% 정상 지급되어야 합니다.
- **4대보험:** 첫 출근 첫날부터 4대보험 취득 신고가 의무적으로 이루어져야 합니다. "수습 끝나고 정규직 발령 나면 가입해 주겠다"는 말은 100% 불법입니다.
- **해고 예고:** 수습 시작일로부터 3개월 이내인 근로자는 30일 전 해고예고 규정이 적용되지 않아 즉시 해고가 가능하지만, '정당한 이유(근로기준법 제23조 제1항)'가 없는 부당해고는 노동위원회 구제신청 대상이 됩니다.

---

## 3. 박과장의 조언

만약 계약서에 "수습 90%"라고 되어 있다면, 내 시급이 **2026년 최저시급 10,030원의 90%인 9,027원 미만으로 떨어지지 않는지** 반드시 계산기를 두드려 확인하세요. 단 1원이라도 모자라면 최저임금법 위반으로 노동청 신고 대상입니다.`
